'use strict';
const KEY='everyday-budget-tracker-v1';
const CATEGORIES={Housing:['Rent','Mortgage payment','Property taxes','Homeowners insurance','HOA / condo fees','Home maintenance','Home repairs','Renter insurance'],Utilities:['Electricity','Natural gas','Heating oil','Water','Sewer','Trash','Internet','Cell phone','Cable / streaming'],Food:['Groceries','Restaurants','Takeout / delivery','Coffee / snacks'],Transport:['Car payment','Car insurance','Gas / fuel','Public transit','Bus fare','Train / subway fare','Monthly transit pass','Commuter rail','Bicycle maintenance','Bike share','Paratransit','Parking','Tolls','Car repairs','Car registration','Rideshare / taxis'],Health:['Medical bills','Health insurance','Dental care','Vision care','Prescription medications','Therapy','Other healthcare'],Debt:['Credit card minimum payment','Credit card extra payment','Student loan','Personal loan','Other loan','Buy now pay later'],Family:['Childcare','School / tuition','Child support','Elder care','Pet care','Pet food'],Lifestyle:['Clothing','Personal care','Gym / fitness','Entertainment','Subscriptions','Travel','Gifts','Donations','Household supplies'],Savings:['Retirement contribution','General savings contribution','Emergency fund contribution','Investments'],Other:['Taxes / fees','Other expense']};
const COLORS=['#316deb','#f4a522','#19ab87','#ef5668','#8b60f4','#28a5d7','#e879a8','#8a98aa','#d67c32','#5265a4','#98b83b','#d54c86'];
const $=id=>document.getElementById(id);const money=x=>Number(x||0).toLocaleString('en-US',{style:'currency',currency:'USD'});const total=a=>a.reduce((x,y)=>x+Number(y.amount||0),0);
function getStore(){return {budgets:[],daily:[]}}
let store=getStore();store.recurring=Array.isArray(store.recurring)?store.recurring:[];store.goal=store.goal||null;store.helpState=store.helpState||'MA';let latest=null;
function save(){return true}
function dateLocal(d=new Date()){const offset=d.getTimezoneOffset()*60000;return new Date(d.getTime()-offset).toISOString().slice(0,10)}
function escapeHTML(s){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function opts(){return '<option value="">Select a category</option>'+Object.entries(CATEGORIES).map(([group,items])=>`<optgroup label="${group}">${items.map(i=>`<option value="${escapeHTML(i)}">${escapeHTML(i)}</option>`).join('')}</optgroup>`).join('')}
function row(category='',amount=''){const div=document.createElement('div');div.className='expense-row';div.innerHTML=`<label>Category<select class="cat">${opts()}</select></label><label>Monthly amount ($)<input class="amount" type="number" min="0" step="0.01" placeholder="Optional" value="${amount}"></label><button type="button" class="remove" aria-label="Remove expense">✕</button>`;div.querySelector('.cat').value=category;div.querySelector('.remove').onclick=()=>{div.remove();preview()};div.querySelectorAll('input,select').forEach(e=>e.addEventListener('input',preview));$('expenseRows').append(div);preview()}
function budgetExpenseRows(){return [...document.querySelectorAll('#expenseRows .expense-row')].map(d=>({category:d.querySelector('.cat').value,raw:d.querySelector('.amount').value.trim()})).filter(r=>r.category||r.raw).map(r=>({...r,amount:r.raw===''?null:Number(r.raw)}));}
function preview(){const expenses=total(budgetExpenseRows().filter(r=>r.amount!=null&&Number.isFinite(r.amount)));const provided=$('income').value.trim()!=='';const income=provided?Number($('income').value):null;$('inputExpenses').textContent=money(expenses);$('inputBalance').textContent=provided?money(income-expenses):'Income not provided';$('inputBalance').className=provided&&income-expenses<0?'negative':''}
function startForm(){const d=dateLocal();$('budgetMonth').value=d.slice(0,7);$('dailyDate').value=d;$('dailyCategory').innerHTML=opts();['Rent','Electricity','Groceries','Public transit','Credit card minimum payment'].forEach(c=>row(c));['income','grossIncome','savings'].forEach(id=>$(id).addEventListener('input',preview))}
$('addExpense').onclick=()=>row();$('clearForm').onclick=()=>{if(confirm('Clear the calculator inputs? Previously saved results will remain.')){$('income').value='';$('savings').value='';$('grossIncome').value='';$('expenseRows').innerHTML='';row();preview()}};
$('budgetForm').onsubmit=e=>{e.preventDefault();const raw=budgetExpenseRows();if(raw.some(r=>(r.amount!==null&&!Number.isFinite(r.amount))||(r.amount!==null&&r.amount<0)||(r.amount!==null&&!r.category))){alert('For any entered amount, choose a category and use a valid nonnegative amount. Empty rows can be skipped.');return;}const expenses=raw.filter(r=>r.category&&r.amount!==null);const income=$('income').value.trim()===''?null:Number($('income').value);const savings=$('savings').value.trim()===''?null:Number($('savings').value);const grossIncome=$('grossIncome').value.trim()===''?null:Number($('grossIncome').value);if([income,savings,grossIncome].some(x=>x!==null&&(!Number.isFinite(x)||x<0)))return;const record={id:crypto.randomUUID?crypto.randomUUID():String(Date.now())+Math.random(),savedAt:new Date().toISOString(),month:$('budgetMonth').value||dateLocal().slice(0,7),income,grossIncome,savings,expenses,partial:income===null||raw.some(r=>r.amount===null)};store.budgets.push(record);if(save()){latest=record;renderResult(record);renderHistory();document.body.dataset.page==='budget'?window.location.assign('money.html'):location.hash='#money'}};
function budgetData(b){const grouped={};b.expenses.forEach(r=>{grouped[r.category]=(grouped[r.category]||0)+Number(r.amount)});const expenses=total(b.expenses);const balance=b.income==null?null:b.income-expenses;return {grouped,expenses,balance,coverage:expenses>0&&b.savings!=null?b.savings/expenses:null}}
function renderResult(b){if(!b)return;latest=b;const x=budgetData(b);$('emptyResult').hidden=true;$('resultContent').hidden=false;$('statIncome').textContent=b.income==null?'Not provided':money(b.income);$('statExpenses').textContent=money(x.expenses);$('statBalance').textContent=x.balance==null?'Not available':money(x.balance);$('statBalance').className=x.balance==null?'':x.balance<0?'negative':'positive';$('statCoverage').textContent=x.coverage===null?'Not applicable':x.coverage.toFixed(1)+' months';renderAssessment(b);renderOverview();renderScenario();renderTrendInsight(b);$('budgetInsight').textContent=b.income==null?`For ${b.month}, you entered ${money(x.expenses)} in monthly expenses. Add take-home income to calculate a remaining balance. This is a partial budget; missing expenses are not counted.`:`For ${b.month}, your listed expenses total ${money(x.expenses)} against ${money(b.income)} take-home income. ${x.balance<0?`Listed expenses exceed income by ${money(-x.balance)}.`:`Your balance after listed expenses is ${money(x.balance)}.`} This may be incomplete if you have not listed all costs.`;let cats=Object.entries(x.grouped).filter(([,v])=>v>0).sort((a,b)=>b[1]-a[1]);let segments=cats.map(([name,value],i)=>({name,value,color:COLORS[i%COLORS.length]}));if(x.balance!==null&&x.balance>0)segments.push({name:'Remaining balance',value:x.balance,color:'#a9b9d2'});drawPie(segments);$('pieLegend').innerHTML=segments.map(s=>`<div class="legend-item"><span><i class="dot" style="background:${s.color}"></i>${escapeHTML(s.name)}</span><b>${money(s.value)}</b></div>`).join('')||'<p>No expenses entered.</p>';const lines=[['Budget month',b.month],['Take-home income',b.income==null?'Not provided':money(b.income)],['Gross household income',b.grossIncome==null?'Not provided':money(b.grossIncome)],['Emergency savings',b.savings==null?'Not provided':money(b.savings)],...b.expenses.map(r=>[r.category+(r.description?' — '+r.description:''),money(r.amount)]),['Total expenses',money(x.expenses)],['Remaining balance',x.balance==null?'Not available':money(x.balance)],['Savings coverage',x.coverage===null?'Not applicable':x.coverage.toFixed(1)+' months']];$('submittedSummary').innerHTML=lines.map(([name,value])=>`<div class="summary-line"><span>${escapeHTML(name)}</span><strong>${escapeHTML(value)}</strong></div>`).join('')}
function drawPie(parts){let canvas=$('budgetPie'),ctx=canvas.getContext('2d'),cx=160,cy=160,r=128;ctx.clearRect(0,0,320,320);let sum=parts.reduce((a,p)=>a+p.value,0);if(sum<=0){ctx.fillStyle='#e1e7f0';ctx.beginPath();ctx.arc(cx,cy,r,0,Math.PI*2);ctx.fill()}else{let angle=-Math.PI/2;parts.forEach(p=>{let stop=angle+p.value/sum*Math.PI*2;ctx.beginPath();ctx.moveTo(cx,cy);ctx.arc(cx,cy,r,angle,stop);ctx.closePath();ctx.fillStyle=p.color;ctx.fill();angle=stop})}ctx.beginPath();ctx.arc(cx,cy,65,0,Math.PI*2);ctx.fillStyle='#fff';ctx.fill();ctx.fillStyle='#273b56';ctx.font='bold 17px system-ui';ctx.textAlign='center';ctx.fillText('Monthly',cx,cy-4);ctx.fillText('budget',cx,cy+19)}
$('printResult').onclick=()=>{if(!latest){alert('Calculate your budget before printing.');return}window.print()};
function csv(rows,headers){const quote=v=>'"'+String(v??'').replace(/"/g,'""')+'"';return [headers,...rows].map(r=>r.map(quote).join(',')).join('\r\n')}
function download(name,body,type){const url=URL.createObjectURL(new Blob([body],{type}));const a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000)}
$('downloadResult').onclick=()=>{if(!latest){alert('Calculate your budget before downloading results.');return}const b=latest,x=budgetData(b),data=[['Budget month',b.month],['Saved at',b.savedAt],['Income',b.income??'Not provided'],['Gross household income',b.grossIncome??'Not provided'],['Savings',b.savings??'Not provided'],...b.expenses.map(r=>[r.category+(r.description?': '+r.description:''),r.amount]),['Total expenses',x.expenses],['Balance',x.balance??'Not available'],['Savings coverage (months)',x.coverage??'N/A']];download(`budget-${b.month}.csv`,csv(data,['Item','Amount / value']),'text/csv;charset=utf-8')};
function addDailyRow(){const wrap=document.createElement('div');wrap.className='daily-extra-row';wrap.innerHTML=`<label>Expense category<select class="daily-extra-category">${opts()}</select></label><label>Amount ($)<input class="daily-extra-amount" type="number" min="0.01" step="0.01" placeholder="0.00"></label><button class="remove" type="button" aria-label="Remove this expense">✕</button>`;wrap.querySelector('.remove').onclick=()=>wrap.remove();$('dailyExtraRows').append(wrap);wrap.querySelector('select').focus()}
$('addDailyRow').onclick=addDailyRow;
$('dailyForm').onsubmit=e=>{e.preventDefault();const date=$('dailyDate').value;const list=[{category:$('dailyCategory').value,raw:$('dailyAmount').value.trim()} ,...[...document.querySelectorAll('.daily-extra-row')].map(r=>({category:r.querySelector('select').value,raw:r.querySelector('input').value.trim()}))];const used=list.filter(r=>r.category||r.raw);if(!used.length){alert('Enter at least one expense.');return}if(used.some(r=>!r.category||r.raw===''||!Number.isFinite(Number(r.raw))||Number(r.raw)<=0)){alert('Each expense you add needs a category and an amount greater than zero. Remove any unused rows.');return}const entries=used.map(r=>({id:crypto.randomUUID?crypto.randomUUID():String(Date.now())+Math.random(),date,category:r.category,amount:Number(r.raw),note:''}));store.daily.push(...entries);if(save()){$('dailyAmount').value='';$('dailyCategory').value='';$('dailyExtraRows').innerHTML='';renderDaily();renderHistory();renderOverview();renderRecurring()}};
function renderDaily(){const now=dateLocal(),month=now.slice(0,7),monthly=store.daily.filter(d=>d.date.slice(0,7)===month);$('todayTotal').textContent=money(total(store.daily.filter(d=>d.date===now)));$('monthDailyTotal').textContent=money(total(monthly));$('dailyCount').textContent=String(monthly.length);$('dailyTable').innerHTML=[...store.daily].sort((a,b)=>b.date.localeCompare(a.date)).slice(0,100).map(d=>`<tr><td>${escapeHTML(d.date)}</td><td>${escapeHTML(d.category)}</td><td class="number">${money(d.amount)}</td><td><button type="button" class="outline" data-edit="${escapeHTML(d.id)}">Edit</button> <button type="button" class="subtle" data-delete="${escapeHTML(d.id)}">Delete</button></td></tr>`).join('')||'<tr><td colspan="4">No daily spending has been logged yet.</td></tr>';document.querySelectorAll('[data-edit]').forEach(btn=>btn.onclick=()=>{const d=store.daily.find(x=>x.id===btn.dataset.edit);if(!d)return;const response=prompt('New amount ($) for '+d.category,d.amount);if(response===null)return;const n=Number(response);if(!Number.isFinite(n)||n<=0){alert('Enter a positive amount.');return}d.amount=n;save();renderDaily();renderHistory();renderOverview()});document.querySelectorAll('[data-delete]').forEach(btn=>btn.onclick=()=>{if(confirm('Delete this daily expense?')){store.daily=store.daily.filter(d=>d.id!==btn.dataset.delete);save();renderDaily();renderHistory();renderOverview();renderRecurring()}})}
$('exportDaily').onclick=()=>download('daily-expenses.csv',csv([...store.daily].sort((a,b)=>a.date.localeCompare(b.date)).map(d=>[d.date,d.category,d.amount]),['Date','Category','Amount']),'text/csv;charset=utf-8');
$('exportAll').onclick=()=>download('everyday-budget-backup.json',JSON.stringify({app:'Everyday Budget & Expense Tracker',version:1,exportedAt:new Date().toISOString(),...store},null,2),'application/json');
$('importFile').onchange=async e=>{const file=e.target.files[0];if(!file)return;try{const data=JSON.parse(await file.text());if(!Array.isArray(data.budgets)||!Array.isArray(data.daily)||data.budgets.some(b=>!Array.isArray(b.expenses)||typeof b.month!=='string'||(b.income!==null&&!Number.isFinite(b.income)))||data.daily.some(d=>typeof d.date!=='string'||!Number.isFinite(d.amount)))throw Error('Invalid backup');if(!confirm(`Restore ${data.budgets.length} budget records and ${data.daily.length} daily expenses? Existing records will be kept.`))return;let b=new Map(store.budgets.map(x=>[x.id,x])),d=new Map(store.daily.map(x=>[x.id,x]));data.budgets.forEach(x=>{if(x.id)b.set(x.id,x)});data.daily.forEach(x=>{if(x.id)d.set(x.id,x)});store={budgets:[...b.values()],daily:[...d.values()]};if(save()){initDisplay();alert('Backup restored.')}}catch{alert('The selected file is not a valid budget tracker backup.')}finally{e.target.value=''}};
function trendSvg(id,series,labels,colors){const svg=$(id);const W=600,H=240,L=52,R=18,T=25,B=42;const all=series.flatMap(s=>s.values).filter(Number.isFinite);const min=Math.min(0,...all),max=Math.max(1,...all);const y=v=>T+(max-v)/(max-min)*(H-T-B);const x=i=>L+i*(W-L-R)/Math.max(1,labels.length-1);let html='';for(let i=0;i<=4;i++){let val=min+(max-min)*i/4,yy=y(val);html+=`<line x1="${L}" y1="${yy}" x2="${W-R}" y2="${yy}" stroke="#e0e8f2"/><text x="${L-7}" y="${yy+4}" text-anchor="end" font-size="10" fill="#6b7e98">${Math.round(val).toLocaleString()}</text>`}labels.forEach((t,i)=>{if(labels.length<=7||i%Math.ceil(labels.length/7)===0||i===labels.length-1)html+=`<text x="${x(i)}" y="${H-13}" text-anchor="middle" font-size="10" fill="#6b7e98">${escapeHTML(t)}</text>`});series.forEach((s,k)=>{const path=s.values.map((v,i)=>(i?'L':'M')+x(i).toFixed(2)+' '+y(v).toFixed(2)).join(' ');html+=`<path d="${path}" stroke="${colors[k]}" stroke-width="2.6" fill="none"/>`;s.values.forEach((v,i)=>html+=`<circle cx="${x(i)}" cy="${y(v)}" r="3.3" fill="${colors[k]}"><title>${escapeHTML(labels[i])}: ${money(v)}</title></circle>`) });svg.innerHTML=html}
function emptySvg(id,msg){$(id).innerHTML=`<text x="300" y="115" text-anchor="middle" fill="#7688a2" font-size="15">${escapeHTML(msg)}</text>`}
function renderHistory(){const sorted=[...store.budgets].sort((a,b)=>a.month.localeCompare(b.month)||a.savedAt.localeCompare(b.savedAt));const perMonth=new Map();sorted.forEach(b=>perMonth.set(b.month,b));const recent=[...perMonth.values()].slice(-12);if(!recent.length)emptySvg('monthlyTrend','Calculate a budget to start your trend.');else trendSvg('monthlyTrend',[{values:recent.map(b=>b.income??0)},{values:recent.map(b=>budgetData(b).expenses)},{values:recent.map(b=>budgetData(b).balance??0)}],recent.map(b=>b.month.slice(2)),['#2466dd','#ec9051','#1aa78a']);const days=Array.from({length:14},(_,i)=>{let d=new Date();d.setHours(12,0,0,0);d.setDate(d.getDate()-(13-i));return dateLocal(d)});const values=days.map(date=>total(store.daily.filter(d=>d.date===date)));if(!store.daily.length)emptySvg('dailyTrend','Log daily expenses to see your trend.');else trendSvg('dailyTrend',[{values}],days.map(d=>d.slice(5)),['#2466dd']);$('historyTable').innerHTML=[...store.budgets].sort((a,b)=>b.savedAt.localeCompare(a.savedAt)).map(b=>`<tr><td>${escapeHTML(new Date(b.savedAt).toLocaleDateString())}</td><td>${escapeHTML(b.month)}</td><td>${b.income==null?'—':money(b.income)}</td><td>${money(budgetData(b).expenses)}</td><td>${budgetData(b).balance==null?'—':money(budgetData(b).balance)}</td><td><button type="button" class="outline" data-view="${escapeHTML(b.id)}">View</button> <button type="button" class="subtle" data-remove-budget="${escapeHTML(b.id)}">Delete</button></td></tr>`).join('')||'<tr><td colspan="6">No saved budgets yet.</td></tr>';document.querySelectorAll('[data-view]').forEach(el=>el.onclick=()=>{const b=store.budgets.find(b=>b.id===el.dataset.view);if(b){renderResult(b);location.hash='#money'}});document.querySelectorAll('[data-remove-budget]').forEach(el=>el.onclick=()=>{if(confirm('Delete this saved budget?')){store.budgets=store.budgets.filter(b=>b.id!==el.dataset.removeBudget);save();const last=store.budgets.at(-1);if(latest?.id===el.dataset.removeBudget){latest=last||null;if(last)renderResult(last);else{$('emptyResult').hidden=false;$('resultContent').hidden=true}}renderHistory()}})}
function initDisplay(){renderDaily();renderHistory();renderGoals();renderRecurring();renderOverview();renderOverview();renderRecurring();const last=[...store.budgets].sort((a,b)=>a.savedAt.localeCompare(b.savedAt)).at(-1);if(last)renderResult(last);else{latest=null;$('emptyResult').hidden=false;$('resultContent').hidden=true}}


