function renderCaseScenario(){if(!caseSnapshot)return;const s=caseSnapshot;const val=id=>Math.max(0,Number($(id).value)||0);const rental=Math.min(s.fields.caseArrears||0,val('caseGrantRent')),utility=Math.min(s.fields.caseUtilityDebt||0,val('caseGrantEnergy'));const due=Math.max(0,s.arrears-rental-utility);const support=val('caseMonthlySupport');const payment=val('casePayment');const monthly=s.balance===null?null:s.balance+support-payment;const msg=`Illustrative only: after one-time payments, outstanding arrears would be ${money(due)}. ${monthly===null?'Supply take-home income to calculate the scenario monthly balance.':`With monthly support and a new payment amount, the estimated monthly balance would be ${money(monthly)}.`} One-time grants reduce arrears, not recurring monthly costs. Check what funds can legally cover and whether assistance is available.`;$('caseScenario').textContent=msg;}
['caseGrantRent','caseGrantEnergy','caseMonthlySupport','casePayment'].forEach(id=>$(id).addEventListener('input',renderCaseScenario));
$('caseForm').onsubmit=e=>{e.preventDefault();buildCase()};
$('clearCase').onclick=()=>{if(confirm('Clear this household assessment?')){$('caseForm').reset();$('caseExtraRows').innerHTML='';caseSnapshot=null;$('caseResults').hidden=true;['caseGrantRent','caseGrantEnergy','caseMonthlySupport','casePayment'].forEach(id=>$(id).value='');}};
$('downloadCase').onclick=()=>{if(!caseSnapshot){alert('Generate an assessment first.');return}const s=caseSnapshot;const rows=CASE_FIELDS.map(([id,label])=>[label,s.fields[id]??'Not entered']);rows.push(...s.expenses.slice(8).map(e=>[e.name,e.amount]),['Reported issue',s.issue],['Possible contributing factor',s.cause],['Urgency',s.urgency],['State',s.state],['ZIP',s.zip],['Household size',s.size]);rows.push(['Additional needs',s.needs.join('; ')],['Housing situation',s.tenure],['Employment',s.employment],['Already receiving assistance',s.existing],['Already applied',s.applied]);rows.push(...casePlanExport());rows.push(['Total monthly costs',s.sum],['Balance',s.balance??'Not available'],['Housing burden (%)',s.burden?.toFixed(1)??'Not available'],['Arrears',s.arrears]);download('anonymous-housing-assessment.csv',csv(rows,['Measure','Value']),'text/csv;charset=utf-8')};
$('printCase').onclick=()=>{if(!caseSnapshot){alert('Generate an assessment first.');return}document.body.classList.add('printing-case');window.print();document.body.classList.remove('printing-case')};
